import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";import{cn as i,dn as a,fn as o,ln as s,mn as c,pn as l,un as u}from"./chunks/assets.CH6La9WX.js";var d=JSON.parse(`{"title":"Metadata Settings","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-document-repository/user/metadata-settings.md","filePath":"content/plugins/bcew-document-repository/user/metadata-settings.md"}`),f={name:`content/plugins/bcew-document-repository/user/metadata-settings.md`};function p(n,d,f,p,m,h){return e(),r(`div`,null,[...d[0]||=[t(`<h1 id="metadata-settings" tabindex="-1">Metadata Settings <a class="header-anchor" href="#metadata-settings" aria-label="Permalink to “Metadata Settings”">​</a></h1><p>Metadata Settings defines custom fields displayed on documents and used for search, sorting, and filtering.</p><p><img src="`+c+`" alt="Metadata Settings Overview" width="1051" height="725"></p><h2 id="access-and-fields" tabindex="-1">Access and fields <a class="header-anchor" href="#access-and-fields" aria-label="Permalink to “Access and fields”">​</a></h2><p>In WordPress Admin, go to <strong>Document Repository → Metadata Settings</strong>. Admins and users with the configured Document Repository capability can manage fields. The default capability is <code>upload_files</code>.</p><p><img src="`+l+`" alt="Where To Find Metadata Settings" width="161" height="369"></p><p>Each field has a required <strong>Field Label</strong>, a <strong>Field Type</strong> (<code>Text</code>, <code>Date</code>, or <code>Taxonomy</code>), and optional <strong>Description</strong>. Taxonomy fields require terms, one per line; for example, taxonomy Animals with terms Ape, Bear, and Coyote.</p><p><img src="`+o+`" alt="Metadata Field Form" width="558" height="586"></p><p>Field type cannot be changed after creation. Text and Date values may be empty; Taxonomy requires terms. New fields appear on documents with blank values until edited.</p><h2 id="add-a-field" tabindex="-1">Add a field <a class="header-anchor" href="#add-a-field" aria-label="Permalink to “Add a field”">​</a></h2><ol><li>Go to <strong>Document Repository → Metadata Settings</strong> and click <strong>Add New Field</strong>.</li><li>Enter a label and choose Text, Date, or Taxonomy.</li><li>For Taxonomy, enter terms one per line and optionally enable <strong>Multiple Choice</strong>.</li><li>Optionally add a description, then click <strong>Save</strong>.</li></ol><p><img src="`+a+`" alt="Add Metadata Field" width="640" height="412"></p><h2 id="edit-or-delete-a-field" tabindex="-1">Edit or delete a field <a class="header-anchor" href="#edit-or-delete-a-field" aria-label="Permalink to “Edit or delete a field”">​</a></h2><p>Click <strong>Edit</strong> beside a field to update its label, description, or taxonomy terms. Type is locked after creation. Keep at least one taxonomy term. Removing a term immediately removes that term assignment from every document that used it; adding a term does not assign it to existing documents.</p><p>Click <strong>Delete</strong> and confirm to permanently remove the field and all its values. The field disappears from both views.</p><p><img src="`+u+`" alt="Edit Metadata Field" width="1278" height="824"><img src="`+s+`" alt="Delete Metadata Field" width="640" height="496"></p><h2 id="use-metadata" tabindex="-1">Use metadata <a class="header-anchor" href="#use-metadata" aria-label="Permalink to “Use metadata”">​</a></h2><p>Fields appear as columns in standard and spreadsheet views. Edit values per document in either view. Text, date, and taxonomy fields can be searched or filtered by matching text, date, or selected terms.</p><p><img src="`+i+`" alt="Using a Metadata Field" width="640" height="496"></p><p>Create only fields you will use; plan taxonomy terms carefully. If fields are missing, refresh and confirm they exist and you have permission. New fields are blank until document values are edited. Field types are fixed; delete and recreate a field to change type. Keep the number of fields and taxonomy terms manageable for performance.</p>`,20)]])}var m=n(f,[[`render`,p]]);export{d as __pageData,m as default};